import { useEffect, useRef, useState, type ReactNode } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { ArrowDownToLine, ArrowRight, ArrowUpRight, CalendarDays, Check, CheckCheck, ChevronRight, CircleHelp, Clock3, Columns3, Database, FileCheck2, FlaskConical, Grid2X2, Info, ListFilter, LoaderCircle, MapPin, Plus, RefreshCw, Search, ShieldCheck, Sparkles, Undo2, Users, X, AlertTriangle, Fingerprint, FileText, Ban, LockKeyhole } from 'lucide-react';
import type { Cohort, Film } from '@rr/domain';
import { getState, mutateState, downloadExport, request, type AppState, type ProgrammeVersion, type EvidenceSnapshot } from './api';
import { useWorkstation, type Surface, type Mode } from './store';
import { QlooReadinessPanel } from './QlooReadiness';
import { TasteDnaPanel, WhyThisFilm, useTaste } from './TasteDna';

const NAV: {id: Surface; label: string; icon: typeof CalendarDays}[] = [
  {id:'programme',label:'Programme canvas',icon:Columns3}, {id:'taste',label:'Taste DNA',icon:Fingerprint},{id:'cohorts',label:'Audience cohorts',icon:Users},
  {id:'catalogue',label:'Film catalogue',icon:Database}, {id:'coverage',label:'Coverage matrix',icon:Grid2X2},
  {id:'repair',label:'Repair review',icon:Undo2}, {id:'evaluation',label:'Evaluation lab',icon:FlaskConical},
];
const MODE_COPY: Record<Mode, string> = {DEMO:'Synthetic affinity fixture. Reproducible and local.',QLOO:'Live cross-domain evidence. Requires confirmed entities and complete provider responses.',METADATA:'Transparent genre and theme baseline. No cross-domain provider claims.',LLM_ONLY:'Model-only comparison. Available only when a model provider is configured.'};
const money = (n: number) => new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:n % 100 === 0 ? 0 : 2}).format(n/100);
const pct = (n: number | undefined | null) => typeof n === 'number' && Number.isFinite(n) ? `${Math.round(n*100)}%` : 'Unknown';
const date = (s: string, timezone = 'Europe/London') => new Date(s).toLocaleDateString('en-GB',{day:'2-digit',month:'short',timeZone:timezone});
const time = (s: string, timezone = 'Europe/London') => new Date(s).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:timezone});
const newest = <T,>(a: T[]) => a[a.length - 1];
function Badge({children,tone = 'neutral'}: {children: ReactNode;tone?:'green'|'orange'|'red'|'neutral'|'dark'}) {return <span className={`badge ${tone}`}>{children}</span>;}
function Empty({title,children,action}: {title:string;children:ReactNode;action?:ReactNode}) {return <div className="empty-state"><Columns3 size={24} strokeWidth={1.2}/><h3>{title}</h3><p>{children}</p>{action}</div>;}
function Alert({children,tone='warning'}:{children:ReactNode;tone?:'warning'|'info'|'success'}) {return <div className={`alert ${tone}`} role={tone === 'warning' ? 'alert' : 'status'}>{tone==='success'?<Check/>:<Info/>}<div>{children}</div></div>;}

export default function App() {
  const queryClient = useQueryClient();
  const stateQuery = useQuery({queryKey:['state'],queryFn:({signal})=>getState(signal)});
  const ui = useWorkstation();
  const [exporting,setExporting] = useState(false);
  const [exportError,setExportError] = useState<string | null>(null);
  const [withdrawFilm,setWithdrawFilm] = useState<Film | null>(null);
  const [confirmReset,setConfirmReset] = useState(false);
  const mutation = useMutation({onError:()=>{void queryClient.invalidateQueries({queryKey:['state']});},mutationFn:({path,body}:{path:string;body?:unknown})=>mutateState(path,body),onSuccess:(state,variables)=>{
    queryClient.setQueryData(['state'],state); void queryClient.invalidateQueries({queryKey:['films']});
    if(variables.path.includes('/generate') || variables.path === '/api/events') ui.setSelectedVersionId(newest(state.versions)?.id ?? null);
    if(variables.path === '/api/demo/reset') {ui.setSelectedVersionId(null);ui.setMode('DEMO');ui.setSurface('programme');ui.closeEvidence();}
    if(variables.path === '/api/events') {ui.setSurface('repair');setWithdrawFilm(null);}
    const message = variables.path.includes('/approve') ? 'Programme approved. Your version and evidence are preserved.' : variables.path === '/api/events' ? 'Rights change recorded. Review the repair before approving.' : variables.path === '/api/demo/reset' ? 'Demo reset. Start with a clean slate.' : variables.path.includes('/cohorts/') ? 'Cohort updated. Earlier programmes must be regenerated.' : variables.path === '/api/evaluations' ? 'Evaluation complete. Only available evidence was compared.' : 'Programme generated. Review the evidence before approving.';
    ui.setToast(message); setConfirmReset(false);
  }});
  useEffect(()=>{if(!ui.toast)return;const id=setTimeout(()=>ui.setToast(null),5000);return()=>clearTimeout(id);},[ui.toast,ui.setToast]);
  const state = stateQuery.data;
  if(!state) return <div className="loading-screen"><div className="loading-content"><div className="brand-mark" style={{margin:'auto'}}/><h1>Rights &amp; Resonance</h1>{stateQuery.isError?<><p>We couldn’t reach the programming server. Your workspace hasn’t been changed.</p><p>{stateQuery.error.message}</p><button className="button primary" onClick={()=>void stateQuery.refetch()}><RefreshCw size={14}/>Try again</button></>:<><p>Opening your programming workstation</p><LoaderCircle className="spinner" size={20}/></>}</div></div>;
  const version = state.versions.find(v=>v.id===ui.selectedVersionId) ?? newest(state.versions);
  const isStale = !!version && version.status === 'DRAFT' && version.inputRevision !== state.revision;
  const canApprove = !!version && version.status === 'DRAFT' && !isStale;
  const busy = mutation.isPending;
  const modeUnavailable = ui.mode === 'QLOO' && !state.providerStatus.qlooConfigured || ui.mode === 'LLM_ONLY' && !state.providerStatus.llmConfigured;
  const act = (path:string,body?:unknown)=>{mutation.reset();setExportError(null);mutation.mutate({path,body});};
  const generate = ()=>act('/api/programmes/generate',{mode:ui.mode});
  const approve = ()=>version&&act(`/api/programmes/${version.programmeId}/approve`,{versionId:version.id});
  const exportFile = async(kind:'export'|'rights-enquiry')=>{if(!version)return;setExporting(true);setExportError(null);try{await downloadExport(version.id,kind);ui.setToast(kind==='export'?'Programme export downloaded.':'Rights enquiry draft downloaded. Nothing has been sent.');}catch(e){setExportError(e instanceof Error?e.message:'Export failed.');}finally{setExporting(false);}};
  const surfaceTitle: Record<Surface,{title:ReactNode;subtitle:string;eyebrow:string}> = {
    programme:{title:<>Good films.<br className="sr-only"/> <em>Better together.</em></>,subtitle:'Shape a season around your audiences, with the evidence to stand behind it.',eyebrow:'The programming desk'},
    taste:{title:<>Taste is the reason.<br className="sr-only"/> <em>See it.</em></>,subtitle:'The cultural tags behind every recommendation, and the audiences they connect.',eyebrow:'Taste DNA'},
    cohorts:{title:<>Know the people.<br className="sr-only"/> <em>Find the connection.</em></>,subtitle:'Cross-domain cultural seeds make each audience visible in the programme.',eyebrow:'Audience intelligence'},
    catalogue:{title:<>The right film.<br className="sr-only"/> <em>The right conditions.</em></>,subtitle:'A working catalogue, grounded in licence territory, format, runtime and cost.',eyebrow:'Curated film inventory'},
    coverage:{title:<>Every audience.<br className="sr-only"/> <em>In the picture.</em></>,subtitle:'Trace cultural coverage back to the actual evidence behind every selection.',eyebrow:'Cultural coverage'},
    repair:{title:<>Plans change.<br className="sr-only"/> <em>Keep the intention.</em></>,subtitle:'Review what changed, what stayed, and what your audiences might lose.',eyebrow:'Programme continuity'},
    evaluation:{title:<>A stronger programme.<br className="sr-only"/> <em>Put to the test.</em></>,subtitle:'Inspect available evidence methods, their candidate universes and their limitations.',eyebrow:'Evaluation lab'},
  };
  const repairedV = version?.repair?version:[...state.versions].reverse().find(v=>v.repair);
  const repairBefore = state.versions.find(v=>v.id===repairedV?.parentVersionId);
  let barContent: ReactNode = null;
  if(ui.surface==='programme') {
    const used = version?.totalCost??0;
    const summary = version ? <div className="bar-summary"><strong>{money(used)} <span>of {money(state.constraints.budgetPence)}</span></strong><small>{money(state.constraints.budgetPence-used)} remaining · {version.items.length}/{state.slots.length} slots</small></div> : <div className="bar-summary"><strong>{money(state.constraints.budgetPence)}</strong><small>licence budget · {state.slots.length} slots to fill</small></div>;
    barContent = <>{summary}{!version||isStale||version.status==='INVALIDATED'
      ? <button className="button primary" disabled={busy||modeUnavailable} onClick={generate}>{busy?<LoaderCircle className="spinner"/>:<Sparkles/>}{version?'Regenerate':'Generate programme'}</button>
      : <button className="button primary" disabled={!canApprove||busy} onClick={approve}>{version.status==='APPROVED'?<CheckCheck/>:<Check/>}{version.status==='APPROVED'?'Programme approved':'Approve programme'}</button>}</>;
  } else if(ui.surface==='repair' && repairedV && repairBefore) {
    const d = repairedV.totalCost-repairBefore.totalCost;
    barContent = <><div className="bar-summary"><strong>{money(repairedV.totalCost)}</strong><small>{d===0?'no fee change':`${d>0?'+':'−'}${money(Math.abs(d))} vs before`}</small></div><button className="button primary" disabled={busy||!canApprove||version?.id!==repairedV.id} onClick={approve}><Check/>{repairedV.status==='APPROVED'?'Repair approved':'Approve repair'}</button></>;
  }
  return <div className="app">
    <a className="skip-link" href="#main-content">Skip to workstation</a>
    <header className="masthead"><a href="#" onClick={e=>{e.preventDefault();ui.setSurface('programme');}} className="brand" aria-label="Rights and Resonance home"><span className="brand-mark"/><div><div className="brand-name">Rights <i>&amp;</i> Resonance</div><div className="brand-caption">A cinema programming workstation</div></div></a>{ui.toast&&<div className="toast toast-top" role="status"><Check/><span>{ui.toast}</span><button className="icon-button" aria-label="Dismiss notification" onClick={()=>ui.setToast(null)}><X/></button></div>}<div className="masthead-right"><div className="workspace-name"><strong>{state.cinema.name}</strong><span>Independent cinema · {state.constraints.territory}</span></div><button className="button ghost small" onClick={()=>setConfirmReset(true)} disabled={busy}><RefreshCw/><span className="reset-label">Reset demo</span></button><div className="avatar" aria-label="Demo workspace">L</div></div></header>
    <MobileTabs surface={ui.surface} onSelect={ui.setSurface}/>
    <div className="shell"><aside className="sidebar"><div><div className="sidebar-label">Workspace / 01</div><nav className="nav" aria-label="Workstation sections">{NAV.map(n=><button key={n.id} onClick={()=>ui.setSurface(n.id)} className={ui.surface===n.id?'active':''} aria-current={ui.surface===n.id?'page':undefined} title={n.label}><n.icon/><span className="nav-label">{n.label}</span>{n.id==='catalogue'&&<span className="sidebar-count">{state.films.length}</span>}</button>)}</nav></div><div className="sidebar-bottom"><div className="demo-note"><strong><span className="status-dot"/>Demo workspace</strong>Rights, fees and demo affinities are synthetic. No real screening is cleared.<button className="button link" onClick={()=>ui.openEvidence({versionId:version?.id})}>View evidence policy <ArrowUpRight/></button></div><div className="sidebar-footer">Made for the human<br/>behind the programme.</div></div></aside>
    <main className="main" id="main-content"><div className="breadcrumb"><span>Workspace</span><ChevronRight/><span>{NAV.find(n=>n.id===ui.surface)?.label}</span></div>
    <div className="page-heading"><div><div className="eyebrow">{surfaceTitle[ui.surface].eyebrow}</div><h1>{surfaceTitle[ui.surface].title}</h1><p>{surfaceTitle[ui.surface].subtitle}</p></div><div className="heading-actions">{ui.surface==='programme'?<><button className="button" disabled={!version||version.status!=='APPROVED'||isStale||exporting||busy} title={version?.status==='APPROVED'?'Download the approved programme':'Approve a current programme before export'} onClick={()=>void exportFile('export')}><ArrowDownToLine/>Export programme</button><button className="button primary" disabled={busy||modeUnavailable} onClick={generate}>{busy?<LoaderCircle className="spinner"/>:<Sparkles/>}{busy?'Working…':version?'Regenerate':'Generate programme'}</button></>:ui.surface==='evaluation'?<button className="button primary" disabled={busy} onClick={()=>act('/api/evaluations')}>{busy?<LoaderCircle className="spinner"/>:<FlaskConical/>}{busy?'Comparing…':'Run comparison'}</button>:<button className="button" onClick={()=>ui.openEvidence({versionId:version?.id})}><Fingerprint/>Inspect evidence</button>}</div></div>
    <div className="context-strip"><div className="context-item"><CalendarDays/><div><small>Programming window</small><strong>{date(state.slots[0]?.startAt??new Date().toISOString(),state.cinema.timezone)} – {date(state.slots[state.slots.length-1]?.startAt??new Date().toISOString(),state.cinema.timezone)} {new Date(state.slots[state.slots.length-1]?.startAt??new Date().toISOString()).getUTCFullYear()}</strong></div></div><div className="context-item"><Clock3/><div><small>Screenings</small><strong>{state.slots.length} slots · {state.slots[0]?.format ?? 'DCP'}</strong></div></div><div className="context-item"><Users/><div><small>Audience cohorts</small><strong>{state.cohorts.length} cultural communities</strong></div></div><div className="context-item context-right"><label className="sr-only" htmlFor="evidence-mode">Evidence mode</label><select id="evidence-mode" className="mode-select" value={ui.mode} disabled={busy} onChange={e=>ui.setMode(e.target.value as Mode)}>{(['DEMO','QLOO','METADATA','LLM_ONLY'] as Mode[]).map(m=><option key={m} value={m}>{m.replace('_',' ')} mode</option>)}</select><span className="mode-tag">Synthetic rights</span></div></div>
    {(mutation.error||exportError)&&<div className="alert" role="alert"><AlertTriangle/><div>{exportError??mutation.error?.message}</div><button className="icon-button" aria-label="Dismiss error" onClick={()=>{mutation.reset();setExportError(null);}}><X/></button></div>}
    {modeUnavailable&&<Alert>Live {ui.mode==='QLOO'?'Qloo':'LLM'} is not configured. Choose Demo or Metadata to continue. The live Qloo feasibility gate remains unverified.</Alert>}
    {ui.mode==='QLOO'&&<QlooReadinessPanel/>}
    {stateQuery.isError&&<Alert>The latest refresh failed. You’re viewing the last retrieved workspace; refresh before making decisions.</Alert>}
    {ui.surface==='programme'&&<Programme state={state} version={version} busy={busy} canApprove={canApprove} stale={isStale} onApprove={approve} onWithdraw={setWithdrawFilm} onEnquiry={()=>void exportFile('rights-enquiry')} exporting={exporting} onGenerate={generate} modeUnavailable={modeUnavailable}/>}
    {ui.surface==='taste'&&<TasteDnaPanel cohorts={state.cohorts} films={state.films}/>}
    {ui.surface==='cohorts'&&<Cohorts state={state} busy={busy} onSave={async(id,seeds)=>{mutation.reset();await mutation.mutateAsync({path:`/api/cohorts/${id}`,body:{seeds}});}}/>}
    {ui.surface==='catalogue'&&<Catalogue state={state} onWithdraw={setWithdrawFilm} busy={busy}/>}
    {ui.surface==='coverage'&&<Coverage state={state} version={version}/>}
    {ui.surface==='repair'&&<Repair state={state} version={version} busy={busy} canApprove={canApprove} onApprove={approve}/>}
    {ui.surface==='evaluation'&&<Evaluation state={state}/>}
    <footer className="app-footer"><span>RIGHTS &amp; RESONANCE · PROGRAMMING WITH PURPOSE</span><span>Live Qloo gate: unverified · {state.providerStatus.persistence==='postgres'?'PostgreSQL storage':'Ephemeral demo storage'} · GBP</span></footer>
    </main></div>
    {ui.evidence&&<EvidenceDrawer state={state} fallbackVersion={version}/>}
    {withdrawFilm&&<ConfirmDialog title="Withdraw screening rights?" onClose={()=>setWithdrawFilm(null)}><p>Mark the synthetic licence for <strong>{withdrawFilm.title}</strong> as unavailable. Any affected programme will be invalidated, and the solver will attempt a minimal-change repair.</p><p>The repaired draft will need your approval. This does not contact a real rights holder.</p><div className="edit-actions"><button className="button" onClick={()=>setWithdrawFilm(null)} disabled={busy}>Cancel</button><button className="button accent" disabled={busy} onClick={()=>act('/api/events',{type:'RIGHTS_REVOKED',filmId:withdrawFilm.id})}>{busy?<LoaderCircle className="spinner"/>:<Ban/>}Withdraw rights &amp; repair</button></div></ConfirmDialog>}
    {confirmReset&&<ConfirmDialog title="Reset the demo workspace?" onClose={()=>setConfirmReset(false)}><p>This restores the original 30-film catalogue and three cohorts, and clears your demo programmes, approvals, changes and evaluation runs.</p><div className="edit-actions"><button className="button" disabled={busy} onClick={()=>setConfirmReset(false)}>Cancel</button><button className="button accent" disabled={busy} onClick={()=>act('/api/demo/reset')}><RefreshCw/>Reset demo</button></div></ConfirmDialog>}
    <MobileBar toast={ui.toast} onDismiss={()=>ui.setToast(null)}>{barContent}</MobileBar>
  </div>;
}

function MobileTabs({surface,onSelect}:{surface:Surface;onSelect:(s:Surface)=>void}) {
  const ref = useRef<HTMLElement>(null);
  const [edge,setEdge] = useState({left:false,right:true});
  const measure = ()=>{const el=ref.current;if(!el)return;setEdge({left:el.scrollLeft>4,right:el.scrollLeft+el.clientWidth<el.scrollWidth-4});};
  useEffect(()=>{measure();ref.current?.querySelector<HTMLElement>('button.active')?.scrollIntoView({inline:'center',block:'nearest'});},[surface]);
  return <div className={`mobile-nav-wrap ${edge.left?'fade-left':''} ${edge.right?'fade-right':''}`}><nav ref={ref} className="mobile-nav" aria-label="Workstation navigation" onScroll={measure}>{NAV.map(n=><button key={n.id} className={surface===n.id?'active':''} onClick={()=>onSelect(n.id)} aria-current={surface===n.id?'page':undefined}>{n.label}</button>)}</nav></div>;
}
function MobileBar({toast,onDismiss,children}:{toast:string|null;onDismiss:()=>void;children?:ReactNode}) {
  if(!toast&&!children) return null;
  return <div className="mobile-bar">{toast&&<div className="toast-strip" role="status"><Check/><span>{toast}</span><button className="icon-button" aria-label="Dismiss notification" onClick={onDismiss}><X/></button></div>}{children&&<div className="mobile-bar-row">{children}</div>}</div>;
}
function EvidencePolicy({state,version,onEvidence,onEvaluation}:{state:AppState;version?:ProgrammeVersion;onEvidence:()=>void;onEvaluation:()=>void}) {
  const snapshot = state.evidence.find(e=>e.id===version?.evidenceId);
  return <aside className="policy-card" aria-label="Evidence policy"><div className="policy-main"><div className="mini-heading"><Fingerprint/>Evidence policy</div><h3>Culture suggests. Constraints decide. You approve.</h3><ul><li><b>Affinities are evidence, not forecasts.</b> They guide selection; they are never attendance or sales predictions.</li><li><b>Rights, fees and demo affinities are synthetic.</b> Nothing is cleared, booked or sent. Approval is a local decision record.</li><li><b>Hard constraints always win:</b> territory, rights dates, format, runtime, budget and no duplicates.</li></ul></div><div className="policy-side"><div className="mini-heading"><LockKeyhole/>Provenance</div><div className="policy-badges"><Badge tone={snapshot&&!snapshot.synthetic?'green':'orange'}>{snapshot&&!snapshot.synthetic?(version?.mode==='QLOO'?'Qloo live':version?.mode):'Demo · synthetic'}</Badge><Badge>{state.providerStatus.qlooConfigured?'Qloo key set · gate unverified':'Qloo not connected'}</Badge></div><button className="button link" onClick={onEvidence}>Open evidence ledger <ArrowRight/></button><button className="button link" onClick={onEvaluation}>Open evaluation lab <ArrowRight/></button></div></aside>;
}
function VersionChooser({state,version}:{state:AppState;version?:ProgrammeVersion}){const ui=useWorkstation();return state.versions.length>1?<div className="version-choices"><label htmlFor="version-select">Version</label><select id="version-select" className="select-compact" value={version?.id??''} onChange={e=>ui.setSelectedVersionId(e.target.value)}>{[...state.versions].reverse().map(v=><option key={v.id} value={v.id}>v{v.version} · {v.status.toLowerCase()} · {v.mode}</option>)}</select></div>:<span>{version?`VERSION ${String(version.version).padStart(2,'0')} · ${version.mode}`:'READY TO BEGIN'}</span>;}

function Programme({state,version,busy,canApprove,stale,onApprove,onWithdraw,onEnquiry,exporting,onGenerate,modeUnavailable}:{state:AppState;version?:ProgrammeVersion;busy:boolean;canApprove:boolean;stale:boolean;onApprove:()=>void;onWithdraw:(f:Film)=>void;onEnquiry:()=>void;exporting:boolean;onGenerate:()=>void;modeUnavailable:boolean}) {
 const ui=useWorkstation(); const taste=useTaste().data; const snapshotOf=state.evidence.find(e=>e.id===version?.evidenceId); const remaining=state.constraints.budgetPence-(version?.totalCost??0);
 return <><div className="workspace-grid"><section aria-label="Programme canvas"><div className="section-title"><h2>Your programme</h2><span className="title-meta">{version&&<Badge tone={snapshotOf?.synthetic===false?'green':'orange'}>{snapshotOf?.synthetic===false?(version.mode==='QLOO'?'Qloo live':version.mode):'Demo · synthetic'}</Badge>}<VersionChooser state={state} version={version}/></span></div>
 {!version&&<div className="guided-start"><div className="guided-copy"><div className="eyebrow">Start here</div><h3>Four screenings. Three audiences. One click.</h3><p>The solver picks a feasible, culturally balanced four-film slate within your licence budget, and shows the evidence for every choice.</p><button className="button primary big" onClick={onGenerate} disabled={busy||modeUnavailable}>{busy?<LoaderCircle className="spinner"/>:<Sparkles/>}Generate programme</button></div><ol className="guided-steps" aria-label="How it works"><li><b>1</b><div><strong>Generate</strong><span>A draft slate with evidence</span></div></li><li><b>2</b><div><strong>Approve</strong><span>You make the decision</span></div></li><li><b>3</b><div><strong>Repair</strong><span>When rights change, keep the intent</span></div></li></ol></div>}
 {version&&(version.status==='INVALIDATED'||stale)&&<Alert>{version.invalidationReason??'The inputs have changed since this version was generated.'} Approval is unavailable. Review the newest repair or generate a fresh programme.</Alert>}
 <div className="programme-list">{state.slots.map((slot,index)=>{const item=version?.items.find(i=>i.slotId===slot.id);const film=state.films.find(f=>f.id===item?.filmId);const snapshot=state.evidence.find(e=>e.id===version?.evidenceId); const matrix=snapshot?.affinities;
 return <article className={`programme-row ${item?'':'is-empty'}`} key={slot.id}><div className="slot-number">0{index+1}</div><div><div className="slot-top"><span className="slot-timing">{slot.label} · {time(slot.startAt,state.cinema.timezone)}–{time(slot.endAt,state.cinema.timezone)}</span>{item?<Badge tone={film?.rights.available?'green':'red'}>{film?.rights.available?'Demo rights available':'Rights unavailable'}</Badge>:<Badge>Open slot</Badge>}</div>{item&&film?<><button className="film-title" onClick={()=>ui.openEvidence({filmId:film.id,versionId:version?.id})}>{item.filmTitle}</button><div className="film-subtitle">{film.year} <span aria-hidden="true">/</span> {film.country} <span aria-hidden="true">/</span> {film.runtimeMinutes} min <span aria-hidden="true">/</span> {item.format} <span aria-hidden="true">/</span> {film.genres.join(' · ')}</div><WhyThisFilm taste={taste} film={film} cohorts={state.cohorts}/><div className="film-footer"><div className="cohort-tags">{state.cohorts.filter(c=>typeof matrix?.[c.id]?.[film.id]==='number').sort((a,b)=>(matrix?.[b.id]?.[film.id]??0)-(matrix?.[a.id]?.[film.id]??0)).slice(0,2).map(c=><span className="cohort-chip" key={c.id} title={`${version?.mode.toLowerCase()} rank-percentile evidence: ${pct(matrix?.[c.id]?.[film.id])}`}>{c.name}</span>)}</div><div className="film-actions"><span className="film-cost">{money(item.feePence)}</span><button className="icon-button" title={`Inspect ${film.title} evidence`} aria-label={`Inspect ${film.title} evidence`} onClick={()=>ui.openEvidence({filmId:film.id,versionId:version?.id})}><ArrowUpRight/></button><button className="icon-button" title={`Withdraw rights for ${film.title}`} aria-label={`Withdraw rights for ${film.title}`} disabled={!film.rights.available||busy} onClick={()=>onWithdraw(film)}><Ban/></button></div></div></>:<><h3 className="film-title empty">An invitation to discover</h3><p className="slot-explanation">{index===0?'Generate a programme to find a feasible, culturally balanced selection.':'A film will be selected against the same audience and licensing constraints.'}</p><div className="slot-empty-line"/></>}</div></article>;})}</div>
 <div className="programme-bottom"><p><ShieldCheck/>{version?'Every selection is checked against territory, rights dates, format, runtime and budget.':'The solver fills all four slots together. No duplicate films, no unavailable licences.'}</p><button className="button link" onClick={()=>ui.openEvidence({versionId:version?.id})}>Follow the evidence <ArrowRight/></button></div>
 </section><aside><div className="summary-panel"><div className="eyebrow">The whole picture</div><h2>{version?'A considered balance.':'Make room for everyone.'}</h2><p>{version?'One programme. Three cultural communities. Every selection has a reason.':'A shared cinema experience starts with a programme that reaches beyond one taste.'}</p><div className="status-line">{version?.status==='APPROVED'?<CheckCheck/>:<ShieldCheck/>}{version?.status==='APPROVED'?'Approved demo programme':version?.status==='INVALIDATED'?'Review required · invalidated':version?'Feasible draft · awaiting review':'All four slots ready to programme'}</div><div className="summary-stats">{version?<><div className="summary-stat"><small>Licence budget used</small><strong>{money(version.totalCost)}</strong></div><div className="summary-stat"><small>Budget remaining</small><strong>{money(remaining)}</strong></div></>:<><div className="summary-stat"><small>Licence budget</small><strong>{money(state.constraints.budgetPence)}</strong></div><div className="summary-stat"><small>Slots to fill</small><strong>{state.slots.length}</strong></div></>}</div><div className="coverage-meter"><div className="eyebrow">Cohort coverage · rank-based</div>{state.cohorts.map(c=>{const score=version?.coverage.find(x=>x.cohortId===c.id)?.score;return <div key={c.id}><div className="meter-label"><span>{c.name}</span><span>{score==null?'Awaiting programme':pct(score)}</span></div><div className="meter-track" role="meter" aria-label={`${c.name} coverage`} aria-valuemin={0} aria-valuemax={100} aria-valuenow={score==null?undefined:Math.round(score*100)} aria-valuetext={score==null?'Not yet calculated':pct(score)}><span className={score!=null&&score<.5?'low':score!=null&&score<.75?'medium':''} style={{width:`${(score??0)*100}%`}}/></div></div>;})}</div><div className="panel-rule"/>{version?<><button className="button panel-primary" disabled={!canApprove||busy} onClick={onApprove}>{version.status==='APPROVED'?<CheckCheck/>:<Check/>}{version.status==='APPROVED'?'Programme approved':'Approve programme'}</button><button className="button ghost" disabled={version.status!=='APPROVED'||stale||exporting||busy} onClick={onEnquiry}><FileText/>Rights enquiry draft</button></>:<p className="panel-hint">Generate a programme to see budget and coverage here.</p>}</div><div className="insight-note"><h3><Sparkles/>The curatorial principle</h3><p>Maximise the least-covered cohort first. Then improve average coverage, cultural diversity and budget use. A strong programme should leave no audience behind.</p><button className="button link" onClick={()=>ui.setSurface('coverage')}>Explore cultural coverage <ArrowUpRight/></button></div></aside></div><EvidencePolicy state={state} version={version} onEvidence={()=>ui.openEvidence({versionId:version?.id})} onEvaluation={()=>ui.setSurface('evaluation')}/></>;
}

function Cohorts({state,busy,onSave}:{state:AppState;busy:boolean;onSave:(id:string,seeds:Cohort['seeds'])=>Promise<void>}){return <><p className="section-note">These fictional cohorts describe cultural interests, not personal or demographic profiles. Each needs at least two seeds. Editing seeds invalidates earlier evidence and programmes.</p><div className="cohort-grid">{state.cohorts.map((c,i)=><CohortCard key={`${c.id}-${state.revision}`} cohort={c} index={i} busy={busy} qlooConfigured={state.providerStatus.qlooConfigured} onSave={seeds=>onSave(c.id,seeds)}/>)}</div><div className="lower-strip"><div><div className="mini-heading"><Users/>Cross-domain seeds</div><h3>A taste is bigger than a genre.</h3><p>Books, music, games and film can reveal cultural connections. In Demo mode scores are deterministic synthetic examples. Edited seeds change the next synthetic evidence run; Metadata uses lexical overlap, while live modes require configured providers.</p></div><div><div className="mini-heading"><ShieldCheck/>Provider boundary</div><p>Names must resolve to verified provider entities before a live Qloo run. Ambiguous candidates require explicit confirmation. No API key is ever sent to the browser.</p></div></div></>;}
function CohortCard({cohort,index,busy,qlooConfigured,onSave}:{cohort:Cohort;index:number;busy:boolean;qlooConfigured:boolean;onSave:(seeds:Cohort['seeds'])=>Promise<void>}){const [editing,setEditing]=useState(false);const [text,setText]=useState(cohort.seeds.map(s=>`${s.domain}: ${s.name}`).join('\n'));const [error,setError]=useState('');const save=()=>{const domains=['music','books','places','brands','film','tv','artist','book','movie','video_game'];const lines=text.split('\n').map(s=>s.trim()).filter(Boolean);if(lines.length<2){setError('Add at least two cultural seeds.');return;}const seeds: Cohort['seeds']=[];for(const line of lines){const colon=line.indexOf(':');const domain=line.slice(0,colon).trim();const name=line.slice(colon+1).trim();if(colon<1||!domains.includes(domain)||!name){setError('Use one seed per line: domain: name. Supported domains include artist, book, movie and video_game.');return;}const existing=cohort.seeds.find(seed=>seed.domain===domain&&seed.name===name);seeds.push({domain:domain as Cohort['seeds'][number]['domain'],name,...(existing?.entityId?{entityId:existing.entityId}:{})});}setError('');void onSave(seeds).catch(()=>{});};return <article className="cohort-card"><div className="cohort-index">0{index+1}</div><div className="eyebrow">Cultural community</div><h2>{cohort.name}</h2><p>{cohort.description}</p>{editing?<div><label className="field-label" htmlFor={`seeds-${cohort.id}`}>Seeds · domain: name, one per line</label><textarea id={`seeds-${cohort.id}`} value={text} onChange={e=>setText(e.target.value)} aria-invalid={!!error} aria-describedby={error?`error-${cohort.id}`:undefined}/>{error&&<p id={`error-${cohort.id}`} role="alert" className="reason-text">{error}</p>}<div className="edit-actions"><button className="button small primary" onClick={save} disabled={busy}><Check/>Save seeds</button><button className="button small" disabled={busy} onClick={()=>{setText(cohort.seeds.map(s=>`${s.domain}: ${s.name}`).join('\n'));setError('');setEditing(false);}}>Cancel</button></div></div>:<div className="seed-list">{cohort.seeds.map((s,i)=><span className="seed" key={i}><small>{s.domain.replace('_',' ')}</small>{s.name}</span>)}</div>}<SeedMappings cohort={cohort} configured={qlooConfigured} busy={busy} onSave={onSave}/><div className="cohort-foot"><span>{cohort.seeds.length} cultural seeds</span><button className="button link small" onClick={()=>{if(editing){setText(cohort.seeds.map(s=>`${s.domain}: ${s.name}`).join('\n'));setError('');}setEditing(!editing);}} disabled={busy}>{editing?'Close editor':'Edit seeds'}<ArrowUpRight/></button></div></article>;}

function Catalogue({state,onWithdraw,busy}:{state:AppState;onWithdraw:(film:Film)=>void;busy:boolean}){const ui=useWorkstation();const [eligibleOnly,setEligibleOnly]=useState(false);const filmsQuery=useQuery({queryKey:['films',state.revision],queryFn:()=>request<{films:Film[];eligibility:{filmId:string;slotId:string;eligible:boolean;reasons:string[]}[]}>('/api/films')});const eligibility=filmsQuery.data?.eligibility??[];const films=state.films.filter(f=>(`${f.title} ${f.country} ${f.genres.join(' ')}`.toLowerCase().includes(ui.search.toLowerCase()))&&(!eligibleOnly||eligibility.some(e=>e.filmId===f.id&&e.eligible)));return <><div className="toolbar"><div className="search-field"><Search/><label className="sr-only" htmlFor="film-search">Search films, country or genre</label><input id="film-search" placeholder="Search films, country or genre…" value={ui.search} onChange={e=>ui.setSearch(e.target.value)}/></div><label style={{fontSize:10,display:'flex',gap:8,alignItems:'center'}}><input type="checkbox" checked={eligibleOnly} disabled={!filmsQuery.data} onChange={e=>setEligibleOnly(e.target.checked)}/><ListFilter size={13}/>Eligible in at least one slot</label><span className="eyebrow no-margin">{films.length} / {state.films.length} films</span></div>{filmsQuery.isError&&<Alert>Eligibility could not be loaded. No availability is being assumed.</Alert>}<div className="table-wrap"><table><thead><tr><th>Film / origin</th><th>Runtime</th><th>Formats</th><th>Demo licence</th><th>Eligibility</th><th><span className="sr-only">Actions</span></th></tr></thead><tbody>{films.map(f=>{const rows=eligibility.filter(e=>e.filmId===f.id);const ok=rows.filter(e=>e.eligible);const reasons=[...new Set(rows.flatMap(e=>e.reasons))];return <tr key={f.id}><td><button className="title-cell" onClick={()=>ui.openEvidence({filmId:f.id})}>{f.title}</button><small>{f.year} · {f.country} · {f.genres.join(' / ')}</small></td><td className="mono">{f.runtimeMinutes} min</td><td className="mono">{f.formats.join(' / ')}</td><td className="mono">{money(f.rights.feePence)}<small>{f.rights.territory} · {date(f.rights.availableFrom)}–{date(f.rights.availableTo)}</small></td><td>{!rows.length?<Badge>{filmsQuery.isPending?'Checking…':'Unknown'}</Badge>:<Badge tone={ok.length?'green':'red'}>{ok.length?`${ok.length} / ${state.slots.length} slots`:'Ineligible'}</Badge>}{reasons.length>0&&<div className="reason-text">{reasons.join(' · ')}</div>}</td><td><button className="icon-button" aria-label={`Inspect ${f.title} evidence`} onClick={()=>ui.openEvidence({filmId:f.id})}><ArrowUpRight/></button><button className="icon-button" aria-label={`Withdraw rights for ${f.title}`} title="Withdraw demo rights" disabled={!f.rights.available||busy} onClick={()=>onWithdraw(f)}><Ban/></button></td></tr>;})}</tbody></table></div>{!films.length&&<Empty title="No films found">Try another title, country or genre, or clear the eligibility filter.</Empty>}<p className="helper">All displayed rights and fees are synthetic. A valid rights window must cover the screening runtime. The budget is checked for the complete programme, not one film at a time.</p></>;}

function Coverage({state,version}:{state:AppState;version?:ProgrammeVersion}){const ui=useWorkstation();if(!version)return <Empty title="The connections start here">Generate a programme to see its film-by-cohort evidence matrix and the resulting coverage.<button className="button link" onClick={()=>ui.setSurface('programme')}>Back to programme <ArrowRight/></button></Empty>;const evidence=state.evidence.find(e=>e.id===version.evidenceId);const normalized=evidence?.normalizedAffinities;const matrix=normalized??evidence?.affinities;return <><div className="section-title"><h2>A programme seen from every audience</h2><VersionChooser state={state} version={version}/></div><div className="metric-cards"><div><small>Least-covered cohort</small><strong>{pct(version.objective)}</strong><p>The primary fairness objective</p></div>{version.coverage.map(c=><div key={c.cohortId}><small>{c.cohortName}</small><strong>{pct(c.score)}</strong><p>Mean of two strongest selected films</p></div>)}</div><p className="section-note">{normalized?`Cells show rank-percentile evidence across this version’s fixed ${evidence?.candidateFilmIds.length??state.films.length}-film candidate universe.`:'Cells show raw evidence scores from this version’s immutable snapshot, not normalized cohort coverage.'} Click any cell to inspect its source. Scores are cultural affinity signals, never attendance forecasts.</p><div className="table-wrap"><table className="matrix"><thead><tr><th>Selected film</th>{state.cohorts.map(c=><th key={c.id}>{c.name}</th>)}</tr></thead><tbody>{version.items.map(item=><tr key={item.slotId}><td><button className="title-cell" onClick={()=>ui.openEvidence({filmId:item.filmId,versionId:version.id})}>{item.filmTitle}</button><small>{state.slots.find(s=>s.id===item.slotId)?.label}</small></td>{state.cohorts.map(c=>{const score=matrix?.[c.id]?.[item.filmId];return <td key={c.id}><button className={`matrix-cell ${score==null?'missing':score<.45?'low':score<.75?'mid':''}`} onClick={()=>ui.openEvidence({filmId:item.filmId,cohortId:c.id,versionId:version.id})} aria-label={`${item.filmTitle}, ${c.name}: ${pct(score)}, inspect evidence`}><span>{pct(score)}</span><ArrowUpRight/></button></td>;})}</tr>)}</tbody></table></div><div className="matrix-legend"><span><i className="swatch"/>Stronger evidence</span><span><i className="swatch low"/>Weaker evidence</span><span><i className="swatch missing"/>Unknown, never treated as zero</span><span>{version.mode==='DEMO'?'Synthetic demo evidence':`${version.mode} evidence`}</span></div><div className="lower-strip"><div><div className="mini-heading"><Grid2X2/>How coverage works</div><h3>Strength for each cohort, balance for the whole room.</h3><p>The solver rank-normalises evidence within each cohort using the same full catalogue. A cohort’s coverage is the mean of its two strongest selected films. It first maximises the lowest cohort coverage.</p></div><div><div className="mini-heading"><Fingerprint/>Fixed evidence snapshot</div><p>This view belongs to the selected programme version. Later seed or rights changes cannot silently rewrite the evidence behind an earlier approval.</p></div></div></>;}

function Repair({state,version,busy,canApprove,onApprove}:{state:AppState;version?:ProgrammeVersion;busy:boolean;canApprove:boolean;onApprove:()=>void}){const ui=useWorkstation();const repaired=version?.repair?version:[...state.versions].reverse().find(v=>v.repair);const before=state.versions.find(v=>v.id===repaired?.parentVersionId);const latestEvent=newest(state.events);if(!repaired||!before)return <><Empty title="A programme worth protecting">After generating and approving a programme, withdraw one selected film’s synthetic rights. The system will preserve the previous version and attempt a minimal-change repair.<button className="button link" onClick={()=>ui.setSurface('programme')}>Back to programme <ArrowRight/></button></Empty>{latestEvent?.repairError&&<Alert>No feasible repair was found: {latestEvent.repairError}</Alert>}</>;
 const changed=repaired.items.filter(i=>before.items.find(old=>old.slotId===i.slotId)?.filmId!==i.filmId).length;const delta=repaired.totalCost-before.totalCost;return <>{latestEvent?.repairError&&<Alert>The latest change could not be repaired: {latestEvent.repairError}. The previous repair below is preserved for review.</Alert>}<div className="section-title"><h2>A small change. The full picture.</h2><VersionChooser state={state} version={repaired}/></div>{repaired.status==='DRAFT'&&<Alert tone="info">The earlier programme was invalidated. This repair is a new draft and needs explicit approval.</Alert>}<div className="diff-grid">{[{v:before,label:'Before · preserved snapshot',className:'before'},{v:repaired,label:'After · proposed repair',className:'after'}].map(({v,label,className})=><section key={v.id} className={`diff-panel ${className}`}><div className="eyebrow">{label}</div><Badge tone={v.status==='APPROVED'?'green':v.status==='INVALIDATED'?'red':'orange'}>{v.status}</Badge><h3>{money(v.totalCost)} <span className="muted" style={{fontSize:17}}>total licences</span></h3>{v.items.map(item=>{const differs=before.items.find(i=>i.slotId===item.slotId)?.filmId!==repaired.items.find(i=>i.slotId===item.slotId)?.filmId;return <div className={`diff-row ${differs?'changed':'unchanged'}`} key={item.slotId}><div><span>{item.filmTitle}</span><small>{state.slots.find(s=>s.id===item.slotId)?.label} · {money(item.feePence)}</small></div>{differs?<em className="swap-tag">{v.id===before.id?'Swapped out':'Swapped in'}</em>:<Check size={14} className="muted" aria-label="Unchanged"/>}</div>;})}</section>)}</div>
 {(()=>{const moved=repaired.coverage.map(c=>({c,prev:before.coverage.find(x=>x.cohortId===c.cohortId)?.score})).filter(({c,prev})=>prev==null||Math.abs(c.score-prev)>=0.0005);const held=repaired.coverage.length-moved.length;const minMoved=Math.abs((repaired.objective??0)-(before.objective??0))>=0.0005;const swaps=repaired.items.map(i=>({i,old:before.items.find(o=>o.slotId===i.slotId)})).filter(({i,old})=>old&&old.filmId!==i.filmId);
 return <><div className="diff-callout"><div className="eyebrow">What changed</div>{swaps.length?swaps.map(({i,old})=><p key={i.slotId}><span className="from">{old!.filmTitle}</span> <ArrowRight size={14}/> <strong>{i.filmTitle}</strong> <small>{state.slots.find(s=>s.id===i.slotId)?.label} · {money(i.feePence-old!.feePence)===money(0)?'same fee':`${i.feePence>old!.feePence?'+':'−'}${money(Math.abs(i.feePence-old!.feePence))}`}</small></p>):<p>No screening needed to change.</p>}</div>
 <div className="diff-summary"><div><small>Screenings changed</small><strong>{changed} <span className="muted" style={{fontSize:18}}>of {state.slots.length}</span></strong></div><div><small>Licence fee difference</small><strong>{delta>0?'+':delta<0?'−':''}{money(Math.abs(delta))}</strong></div>{minMoved&&<div><small>Minimum coverage</small><strong>{pct(before.objective)} → {pct(repaired.objective)}</strong></div>}</div>
 {moved.length>0?<div className="table-wrap" style={{marginTop:25}}><table><thead><tr><th>Cohort whose coverage moved</th><th>Before</th><th>After</th><th>Change</th></tr></thead><tbody>{moved.map(({c,prev})=><tr key={c.cohortId} className="moved-row"><td>{c.cohortName}</td><td className="mono">{pct(prev)}</td><td className="mono">{pct(c.score)}</td><td className="mono">{prev==null?'Unknown':`${c.score-prev>=0?'+':'−'}${Math.abs((c.score-prev)*100).toFixed(1)} pp`}</td></tr>)}</tbody></table></div>:null}
 <p className="held-note">{moved.length===0?'No cohort’s coverage changed.':held>0?`${held} other cohort${held===1?'':'s'} unchanged.`:''}{!minMoved&&` Minimum coverage held at ${pct(repaired.objective)}.`}</p></>;})()}<div className="programme-bottom"><p>{repaired.explanation}</p><button className="button primary desk-only" disabled={busy||!canApprove||version?.id!==repaired.id} onClick={onApprove}><Check/>{repaired.status==='APPROVED'?'Repair approved':'Approve repair'}</button></div><div className="events-list"><div className="section-title"><h2>Change ledger</h2><span>{state.events.length} RECORDED EVENTS</span></div>{[...state.events].reverse().map(e=><div className="event-row" key={e.id}><Undo2/><div><strong>{e.type.replaceAll('_',' ').toLowerCase()}</strong><small>{date(e.createdAt)} · {time(e.createdAt)} · {e.invalidatedVersionIds.length} version(s) invalidated</small>{e.repairError&&<span className="reason-text">{e.repairError}</span>}</div></div>)}</div></>;}

function Evaluation({state}:{state:AppState}){const evaluation=newest(state.evaluations);return <><Alert tone="info">Live Qloo feasibility is unverified. There are no fabricated provider results or rankings here. Each comparison records availability as well as measured output.</Alert><div className="evaluation-modes">{(['DEMO','QLOO','METADATA','LLM_ONLY'] as Mode[]).map(mode=>{const available=mode==='DEMO'||mode==='METADATA'||mode==='QLOO'&&state.providerStatus.qlooConfigured||mode==='LLM_ONLY'&&state.providerStatus.llmConfigured;return <section className={`evaluation-card ${available?'active':''}`} key={mode}><Badge tone={available?'green':'neutral'}>{mode==='QLOO'&&available?'Configured · gate pending':available?'Available':'Unavailable'}</Badge><h3>{mode}</h3><p>{MODE_COPY[mode]}</p></section>;})}</div>{evaluation?<>{evaluation.warning&&<Alert>{evaluation.warning}</Alert>}<div className="section-title"><h2>Latest comparison</h2><span>{date(evaluation.createdAt)} · {time(evaluation.createdAt)}</span></div><div className="table-wrap"><table><thead><tr><th>Method</th><th>Result</th><th>Minimum coverage</th><th>Licence cost</th><th>Candidate universe</th><th>Programme / limitation</th></tr></thead><tbody>{evaluation.rows.map(row=><tr key={row.mode}><td className="mono">{row.mode}</td><td><Badge tone={row.status==='SUCCEEDED'?'green':row.status==='FAILED'?'red':'neutral'}>{row.status}</Badge></td><td className="mono">{pct(row.objective)}</td><td className="mono">{row.totalCost==null?'Not measured':money(row.totalCost)}</td><td className="mono">{row.candidateCount!=null?`${row.candidateCount} films`:'Not evaluated'}</td><td>{row.reason??row.selectedFilmIds?.map(id=>state.films.find(f=>f.id===id)?.title??id).join(' · ')??'No result'}</td></tr>)}</tbody></table></div><p className="helper">Scores are internal to each evidence method. A higher score across different methods is not proof of better real-world audience performance. No attendance claims are made.</p></>:<Empty title="An honest comparison starts with a run">Run the comparison to evaluate the available methods. Unconfigured providers will remain visibly unavailable, with no invented scores.</Empty>}<div className="lower-strip"><div><div className="mini-heading"><FlaskConical/>Ablation, not a leaderboard</div><h3>What does cross-domain evidence add?</h3><p>Inspect candidate universes before comparing. Live Qloo uses only confirmed mappings, which may exclude films available to other methods. Inspect feasibility, selection, licence cost and within-method coverage. Real audience value still needs independent validation.</p></div><div><div className="mini-heading"><Database/>Reproducibility</div><p>Demo is deterministic. Every generation stores its input revision, evidence snapshot, workflow trace and programme version. Rights and fees remain illustrative in every mode.</p></div></div></>;}

function useDialog(onClose:()=>void){const ref=useRef<HTMLDivElement>(null);useEffect(()=>{const old=document.activeElement as HTMLElement|null;const oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';ref.current?.querySelector<HTMLElement>('button, [href], input, select, textarea, [tabindex="0"]')?.focus();const key=(e:KeyboardEvent)=>{if(e.key==='Escape'){e.preventDefault();onClose();}if(e.key==='Tab'){const focusable=ref.current?.querySelectorAll<HTMLElement>('button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex="0"]');if(!focusable?.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};document.addEventListener('keydown',key);return()=>{document.removeEventListener('keydown',key);document.body.style.overflow=oldOverflow;old?.focus();};},[onClose]);return ref;}
function ConfirmDialog({title,children,onClose}:{title:string;children:ReactNode;onClose:()=>void}){const ref=useDialog(onClose);return <div className="drawer-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}} style={{alignItems:'center',justifyContent:'center',padding:20}}><div ref={ref} role="dialog" aria-modal="true" aria-labelledby="confirm-title" style={{background:'var(--paper)',maxWidth:480,padding:28,borderRadius:4,boxShadow:'0 20px 60px #0002'}}><div style={{display:'flex',gap:20,alignItems:'start',justifyContent:'space-between'}}><h2 id="confirm-title" style={{fontFamily:'var(--serif)',fontWeight:400,fontSize:30,margin:0}}>{title}</h2><button className="icon-button" aria-label="Close dialog" onClick={onClose}><X/></button></div><div style={{fontSize:12,lineHeight:1.8,color:'var(--muted)'}}>{children}</div></div></div>;}

function EvidenceDrawer({state,fallbackVersion}:{state:AppState;fallbackVersion?:ProgrammeVersion}){const ui=useWorkstation();const ref=useDialog(ui.closeEvidence);const selected=ui.evidence!;const version=state.versions.find(v=>v.id===selected.versionId)??fallbackVersion;const snapshot=state.evidence.find(e=>e.id===version?.evidenceId);const film=(snapshot?.inputs.films??state.films).find(f=>f.id===selected.filmId);const currentFilm=state.films.find(f=>f.id===selected.filmId);const cohort=(snapshot?.inputs.cohorts??state.cohorts).find(c=>c.id===selected.cohortId);const score=film&&cohort?snapshot?.affinities[cohort.id]?.[film.id]:undefined;const run=state.runs.find(r=>r.versionId===version?.id);return <div className="drawer-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)ui.closeEvidence();}}><div className="drawer" ref={ref} role="dialog" aria-modal="true" aria-labelledby="evidence-title"><div className="drawer-head"><div><div className="eyebrow">Evidence ledger</div><h2 id="evidence-title">{film?.title??'Behind the programme'}</h2><p>{cohort?`${cohort.name} · `:''}{version?`${version.mode} · ${version.status.toLowerCase()} · immutable version snapshot`:'Current workspace · no programme snapshot yet'}</p></div><button className="icon-button" aria-label="Close evidence" onClick={ui.closeEvidence}><X/></button></div><div className="drawer-content">
 <section className="evidence-section"><h3><span>01</span>Cultural evidence / Qloo</h3><Badge tone={snapshot?.synthetic?'orange':'neutral'}>{snapshot?.sourceLabel??'No programme evidence yet'}</Badge>{typeof score==='number'?<><div className="evidence-emphasis">{pct(score)}</div><p>{snapshot?.mode} rank-percentile affinity evidence for this film and cohort, normalized on its fixed candidate universe. This is not a ticket-sales probability; programme coverage combines the strongest two films.</p></>:cohort&&<p>Evidence is unknown. Missing data is never replaced with zero.</p>}<p>{snapshot?.claim??'Demo affinity scores are synthetic fixtures. No recorded or live Qloo response is being represented.'}</p><dl><dt>Qloo connection</dt><dd>{state.providerStatus.qlooConfigured?'Configured; live feasibility gate UNVERIFIED':'Not configured; live feasibility gate UNVERIFIED'}</dd><dt>Film mapping</dt><dd>{currentFilm?.mappingStatus??'Select a film to inspect mapping'}{currentFilm?.qlooEntityId?` · ${currentFilm.qlooEntityId}`:''}</dd><dt>Provider responses</dt><dd>{snapshot?.providerResponses.length??0} stored response(s)</dd><dt>Candidate universe</dt><dd>{snapshot?.candidateFilmIds.length??state.films.length} fixed candidates</dd></dl><QlooReadinessPanel/>{currentFilm&&<FilmMapping film={currentFilm} configured={state.providerStatus.qlooConfigured}/>}{snapshot?.warnings.map((w,i)=><p key={i} className="reason-text">{w}</p>)}{snapshot&&<details><summary>Inspect cultural evidence data</summary><pre>{JSON.stringify({mode:snapshot.mode,synthetic:snapshot.synthetic,sourceLabel:snapshot.sourceLabel,affinities:film?Object.fromEntries(Object.entries(snapshot.affinities).map(([id,row])=>[id,row[film.id]??null])):snapshot.affinities,providerResponses:snapshot.providerResponses},null,2)}</pre></details>}</section>
 <section className="evidence-section"><h3><span>02</span>Local operational constraints</h3><Badge tone="orange">Synthetic rights &amp; fees</Badge><p>Operational constraints are local catalogue data. Cultural affinity does not establish screening rights.</p><dl><dt>Territory</dt><dd>{state.constraints.territory}</dd><dt>Programme budget</dt><dd>{money(snapshot?.inputs.constraints.budgetPence??state.constraints.budgetPence)}</dd>{film&&<><dt>Snapshot rights</dt><dd>{film.rights.available===true?'Available':film.rights.available===false?'Unavailable':'Unknown'} · {film.rights.territory}</dd><dt>Current rights</dt><dd>{currentFilm?.rights.available===true?'Available':currentFilm?.rights.available===false?'Unavailable':'Unknown'}</dd><dt>Licence window</dt><dd>{date(film.rights.availableFrom)} – {date(film.rights.availableTo)}</dd><dt>Runtime / format</dt><dd>{film.runtimeMinutes} minutes · {film.formats.join(', ')}</dd><dt>Licence fee</dt><dd>{money(film.rights.feePence)} · {film.rights.source.toLowerCase()}</dd></>}</dl><p>Rights dates, territory, exact slot format, runtime, budget and no duplicate films are hard constraints.</p></section>
 <section className="evidence-section"><h3><span>03</span>Solver decision</h3>{version?<><Badge tone="green">Deterministic constrained selection</Badge><p>{version.explanation}</p><dl><dt>Minimum coverage</dt><dd>{pct(version.objective)}</dd><dt>Total licence cost</dt><dd>{money(version.totalCost)}</dd><dt>Input revision</dt><dd>{version.inputRevision}{version.inputRevision!==state.revision?' · changed since this solve':''}</dd><dt>Status</dt><dd>{version.status}</dd><dt>Snapshot ID</dt><dd className="mono">{version.evidenceId}</dd></dl><details><summary>Inspect objective breakdown</summary><pre>{JSON.stringify(version.objectiveBreakdown,null,2)}</pre></details></>:<p>No solve has been run. Generate a programme to record its choices and objective values.</p>}</section>
 <section className="evidence-section"><h3><span>04</span>Agent / workflow commentary</h3><p>Workflow commentary describes the recorded steps. It is separate from cultural evidence, local constraints and the solver’s decision.</p>{run?<>{run.steps.map((step,i)=><div key={i} className="event-row">{step.status==='ERROR'?<AlertTriangle size={13}/>:<Check size={13}/>}<div><strong>{step.node}</strong><small>{step.status} · {step.detail}</small></div></div>)}<details><summary>Inspect recorded workflow</summary><pre>{JSON.stringify(run,null,2)}</pre></details></>:<p>No recorded programme workflow to display yet.</p>}</section><p className="helper">Rights &amp; Resonance supports the programmer’s decision. Approval is a local workflow action, never a rights clearance or an external enquiry.</p>
 </div></div></div>;}

type EntityCandidate = {entityId:string;name:string;type:string|null;releaseYear:number|null};
const domainTypes: Record<string,string> = {music:'urn:entity:artist',artist:'urn:entity:artist',books:'urn:entity:book',book:'urn:entity:book',film:'urn:entity:movie',movie:'urn:entity:movie',video_game:'urn:entity:videogame',places:'urn:entity:place',brands:'urn:entity:brand',tv:'urn:entity:tv_show'};
function EntityPicker({query,type,filmId,disabled,onConfirm}:{query:string;type:string;filmId?:string;disabled?:boolean;onConfirm:(candidate:EntityCandidate)=>Promise<void>}) {
 const [candidates,setCandidates]=useState<EntityCandidate[]|null>(null);const [selected,setSelected]=useState<EntityCandidate|null>(null);const [pending,setPending]=useState(false);const [error,setError]=useState('');
 const search=async()=>{setPending(true);setError('');setSelected(null);try{const result=await request<{candidates:EntityCandidate[];warnings?:string[]}>('/api/qloo/resolve',{method:'POST',body:JSON.stringify(filmId?{filmId}:{query,type})});setCandidates(result.candidates.filter(c=>c.type===type));if(result.warnings?.length)setError(result.warnings.join(' '));}catch(e){setError(e instanceof Error?e.message:'Entity search failed.');}finally{setPending(false);}};
 const confirm=async()=>{if(!selected)return;setPending(true);setError('');try{await onConfirm(selected);setSelected(null);setCandidates(null);}catch(e){setError(e instanceof Error?e.message:'Mapping could not be confirmed.');}finally{setPending(false);}};
 return <div className="entity-picker"><button className="button small" disabled={disabled||pending} onClick={()=>void search()}>{pending?<LoaderCircle className="spinner"/>:<Search/>}Search Qloo for “{query}”</button>{error&&<p className="reason-text" role="alert">{error}</p>}{candidates&&<div><p className="helper">Choose the exact entity. Names alone do not establish a match. Confirming changes the inputs and may create a new programme draft.</p>{candidates.length===0?<p className="helper">No matching-type candidates returned. No mapping was saved.</p>:<div className="entity-results" role="radiogroup" aria-label={`Qloo candidates for ${query}`}>{candidates.map(c=><label key={c.entityId} className={`entity-choice ${selected?.entityId===c.entityId?'selected':''}`}><input type="radio" name={`entity-${filmId??query}`} checked={selected?.entityId===c.entityId} disabled={disabled||pending} onChange={()=>setSelected(c)}/><span>{c.name}{c.releaseYear?` (${c.releaseYear})`:''}<small>{c.type}<br/>{c.entityId}</small></span></label>)}</div>}{selected&&<div className="edit-actions"><button className="button small primary" disabled={disabled||pending} onClick={()=>void confirm()}><Check/>Confirm “{selected.name}”</button><button className="button small" disabled={pending} onClick={()=>{setSelected(null);setCandidates(null);}}>Cancel</button></div>}</div>}</div>;
}
function FilmMapping({film,configured}:{film:Film;configured:boolean}){const client=useQueryClient();const ui=useWorkstation();const save=async(candidate:EntityCandidate)=>{const state=await mutateState('/api/qloo/confirm',{filmId:film.id,entityId:candidate.entityId});client.setQueryData(['state'],state);await client.invalidateQueries({queryKey:['films']});ui.setToast(`Mapping confirmed for ${film.title}. Review any new programme draft.`);};return <details className="mapping-details"><summary>Resolve live film mapping</summary>{configured?<><p>Match this catalogue film to a live Qloo movie entity. Check title and release year against <strong>{film.title} ({film.year})</strong>.</p><EntityPicker key={`${film.id}-${film.qlooEntityId}`} query={film.title} type="urn:entity:movie" filmId={film.id} onConfirm={save}/></>:<p>Configure QLOO_API_KEY on the server to search live entities. No mapping candidates are simulated.</p>}</details>;}
function SeedMappings({cohort,configured,busy,onSave}:{cohort:Cohort;configured:boolean;busy:boolean;onSave:(seeds:Cohort['seeds'])=>Promise<void>}){return <details className="mapping-details"><summary>Live seed mappings · {cohort.seeds.filter(s=>s.entityId).length}/{cohort.seeds.length}</summary>{configured?<div>{cohort.seeds.map((seed,index)=><div className="seed-mapping" key={`${index}-${seed.entityId??''}`}><div className="field-label">{seed.name} <Badge tone={seed.entityId?'green':'neutral'}>{seed.entityId?'Resolved':'Unmapped'}</Badge></div>{seed.entityId&&<p className="helper mono">{seed.entityId}</p>}<EntityPicker query={seed.name} type={domainTypes[seed.domain]??`urn:entity:${seed.domain}`} disabled={busy} onConfirm={async candidate=>{await onSave(cohort.seeds.map((s,i)=>i===index?{...s,entityId:candidate.entityId}:s));}}/></div>)}</div>:<p className="helper">Live search needs a server-side Qloo key. The demo uses synthetic cultural evidence and contains no fabricated entity IDs.</p>}</details>;}
